10	package org.elasticsearch.dissect;
11	
12	import java.nio.charset.StandardCharsets;
13	import java.util.ArrayList;
14	import java.util.Arrays;
15	import java.util.EnumSet;
16	import java.util.Iterator;
17	import java.util.LinkedHashSet;
18	import java.util.List;
19	import java.util.Map;
20	import java.util.Set;
21	import java.util.function.Function;
22	import java.util.regex.Matcher;
23	import java.util.regex.Pattern;
24	import java.util.stream.Collectors;
25	
26	/**
27	 * Splits (dissects) a string into its parts based on a pattern.
28	 * <p>A dissect pattern is composed of a set of keys and delimiters.
29	 * For example the dissect pattern: <pre>%{a} %{b},%{c}</pre> has 3 keys (a,b,c) and two delimiters (space and comma). This pattern will
30	 * match a string of the form: <pre>foo bar,baz</pre> and will result a key/value pairing of <pre>a=foo, b=bar, and c=baz.</pre>
31	 * <p>Matches are all or nothing. For example, the same pattern will NOT match <pre>foo bar baz</pre> since all of the delimiters did not
32	 * match. (the comma did not match)
33	 * <p>Dissect patterns can optionally have modifiers. These modifiers instruct the parser to change its behavior. For example the
34	 * dissect pattern of <pre>%{a},%{b}:%{c}</pre> would not match <pre>foo,bar,baz</pre> since there the colon never matches.
35	 * <p>Modifiers appear to the left or the right of the key name. The supported modifiers are:
36	 * <ul>
37	 * <li>{@code ->} Instructs the parser to ignore repeating delimiters to the right of the key. Example: <pre>
38	 * pattern: {@code %{a->} %{b} %{c}}
39	 * string: {@code foo         bar baz}
40	 * result: {@code a=foo, b=bar, c=baz}
41	 * </pre></li>
42	 * <li>{@code +} Instructs the parser to appends this key's value to value of prior key with the same name.
43	 * Example: <pre>
44	 * pattern: {@code %{a} %{+a} %{+a}}
45	 * string: {@code foo bar baz}
46	 * result: {@code a=foobarbaz}
47	 * </pre></li>
48	 * <li>{@code /} Instructs the parser to appends this key's value to value of a key based based on the order specified after the
49	 * {@code /}. Requires the {@code +} modifier to also be present in the key. Example: <pre>
50	 * pattern: {@code %{a} %{+a/2} %{+a/1}}
51	 * string: {@code foo bar baz}
52	 * result: {@code a=foobazbar}
53	 * </pre>
54	 * </li>
55	 * <li>{@code *} Instructs the parser to ignore the name of this key, instead use the value of key as the key name.
56	 * Requires another key with the same name and the {@code &} modifier to be the value. Example: <pre>
57	 * pattern: {@code %{*a} %{b} %{&a}}
58	 * string: {@code foo bar baz}
59	 * result: {@code foo=baz, b=bar}
60	 * </pre></li>
61	 * <li>{@code &} Instructs the parser to ignore this key and place the matched value to a key of the same name with the {@code *} modifier.
62	 * Requires another key with the same name and the {@code *} modifier.
63	 * Example: <pre>
64	 * pattern: {@code %{*a} %{b} %{&a}}
65	 * string: {@code foo bar baz}
66	 * result: {@code foo=baz, b=bar}
67	 * </pre></li>
68	 * <li>{@code ?} Instructs the parser to ignore this key. The key name exists only for the purpose of human readability. Example
69	 * <pre>
70	 *  pattern: {@code %{a} %{?skipme} %{c}}
71	 *  string: {@code foo bar baz}
72	 *  result: {@code a=foo, c=baz}
73	 * </pre>
74	 * </ul>
75	 * <p>Empty key names patterns are also supported. They behave just like the {@code ?} modifier, except the name is not required.
76	 * The result will simply be ignored. Example
77	 * <pre>
78	 * pattern: {@code %{a} %{} %{c}}
79	 * string: {@code foo bar baz}
80	 * result: {@code a=foo, c=baz}
81	 * </pre>
82	
83	 * <p>
84	 * Inspired by the Logstash Dissect Filter by Guy Boertje
85	 */
86	public final class DissectParser {
87	    private static final Pattern LEADING_DELIMITER_PATTERN = Pattern.compile("^(.*?)%\\{");
88	    private static final Pattern KEY_DELIMITER_FIELD_PATTERN = Pattern.compile("%\\{([^}]*?)}(.+?(?=%\\{)|.*$)", Pattern.DOTALL);
89	    private static final EnumSet<DissectKey.Modifier> ASSOCIATE_MODIFIERS = EnumSet.of(
90	        DissectKey.Modifier.FIELD_NAME,
91	        DissectKey.Modifier.FIELD_VALUE
92	    );
93	    private static final EnumSet<DissectKey.Modifier> APPEND_MODIFIERS = EnumSet.of(
94	        DissectKey.Modifier.APPEND,
95	        DissectKey.Modifier.APPEND_WITH_ORDER
96	    );
97	    private static final Function<DissectPair, String> KEY_NAME = val -> val.key().getName();
98	    private final List<DissectPair> matchPairs;
99	    private final String pattern;
100	    private String leadingDelimiter = "";
101	    private final int maxMatches;
102	    private final int maxResults;
103	    private final int appendCount;
104	    private final int referenceCount;
105	    private final String appendSeparator;
106	
107	    public DissectParser(String pattern, String appendSeparator) {
108	        this.pattern = pattern;
109	        this.appendSeparator = appendSeparator == null ? "" : appendSeparator;
110	        Matcher matcher = LEADING_DELIMITER_PATTERN.matcher(pattern);
111	        while (matcher.find()) {
112	            leadingDelimiter = matcher.group(1);
113	        }
114	        List<DissectPair> dissectPairs = new ArrayList<>();
115	        matcher = KEY_DELIMITER_FIELD_PATTERN.matcher(pattern.substring(leadingDelimiter.length()));
116	        while (matcher.find()) {
117	            DissectKey key = new DissectKey(matcher.group(1));
118	            String delimiter = matcher.group(2);
119	            dissectPairs.add(new DissectPair(key, delimiter));
120	        }
121	        this.maxMatches = dissectPairs.size();
122	        this.maxResults = Long.valueOf(
123	            dissectPairs.stream().filter(dissectPair -> dissectPair.key().skip() == false).map(KEY_NAME).distinct().count()
124	        ).intValue();
125	        if (this.maxMatches == 0 || maxResults == 0) {
126	            throw new DissectException.PatternParse(pattern, "Unable to find any keys or delimiters.");
127	        }
128	        // append validation - look through all of the keys to see if there are any keys that need to participate in an append operation
129	        // but don't have the '+' defined
130	        Set<String> appendKeyNames = dissectPairs.stream()
131	            .filter(dissectPair -> APPEND_MODIFIERS.contains(dissectPair.key().getModifier()))
132	            .map(KEY_NAME)
133	            .collect(Collectors.toSet());
134	        if (appendKeyNames.size() > 0) {
135	            List<DissectPair> modifiedMatchPairs = new ArrayList<>(dissectPairs.size());
136	            for (DissectPair p : dissectPairs) {
137	                if (p.key().getModifier().equals(DissectKey.Modifier.NONE) && appendKeyNames.contains(p.key().getName())) {
138	                    modifiedMatchPairs.add(new DissectPair(new DissectKey(p.key(), DissectKey.Modifier.APPEND), p.delimiter()));
139	                } else {
140	                    modifiedMatchPairs.add(p);
141	                }
142	            }
143	            dissectPairs = modifiedMatchPairs;
144	        }
145	        appendCount = appendKeyNames.size();
146	
147	        // reference validation - ensure that '*' and '&' come in pairs
148	        Map<String, List<DissectPair>> referenceGroupings = dissectPairs.stream()
149	            .filter(dissectPair -> ASSOCIATE_MODIFIERS.contains(dissectPair.key().getModifier()))
150	            .collect(Collectors.groupingBy(KEY_NAME));
151	        for (Map.Entry<String, List<DissectPair>> entry : referenceGroupings.entrySet()) {
152	            if (entry.getValue().size() != 2) {
153	                throw new DissectException.PatternParse(
154	                    pattern,
155	                    "Found invalid key/reference associations: '"
156	                        + entry.getValue().stream().map(KEY_NAME).collect(Collectors.joining(","))
157	                        + "' Please ensure each '*<key>' is matched with a matching '&<key>"
158	                );
159	            }
160	        }
161	
162	        referenceCount = referenceGroupings.size() * 2;
163	        this.matchPairs = List.copyOf(dissectPairs);
164	    }
165	
166	    /**
167	     * Entry point to dissect a string into its parts.
168	     *
169	     * @param inputString The string to dissect
170	     * @return the key/value Map of the results
171	     * @throws DissectException if unable to dissect a pair into its parts.
172	     */
173	    public Map<String, String> parse(String inputString) {
174	        /**
175	         *
176	         * This implements a naive string matching algorithm. The string is walked left to right, comparing each byte against
177	         * another string's bytes looking for matches. If the bytes match, then a second cursor looks ahead to see if all the bytes
178	         * of the other string matches. If they all match, record it and advances the primary cursor to the match point. If it can not match
179	         * all of the bytes then progress the main cursor. Repeat till the end of the input string. Since the string being searching for
180	         * (the delimiter) is generally small and rare the naive approach is efficient.
181	         *
182	         * In this case the string that is walked is the input string, and the string being searched for is the current delimiter.
183	         * For example for a dissect pattern of {@code %{a},%{b}:%{c}} the delimiters (comma then colon) are searched for in the
184	         * input string. At class construction the list of keys+delimiters are found (dissectPairs), which allows the use of that ordered
185	         * list to know which delimiter to use for the search. The delimiters is progressed once the current delimiter is matched.
186	         *
187	         * There are two special cases that requires additional parsing beyond the standard naive algorithm. Consecutive delimiters should
188	         * results in a empty matches unless the {@code ->} is provided. For example given the dissect pattern of
189	         * {@code %{a},%{b},%{c},%{d}} and input string of {@code foo,,,} the match should be successful with empty values for b,c and d.
190	         * However, if the key modifier {@code ->}, is present it will simply skip over any delimiters just to the right of the key
191	         * without assigning any values. For example {@code %{a->},{%b}} will match the input string of {@code foo,,,,,,bar} with a=foo and
192	         * b=bar.
193	         *
194	         */
195	        DissectMatch dissectMatch = new DissectMatch(appendSeparator, maxMatches, maxResults, appendCount, referenceCount);
196	        Iterator<DissectPair> it = matchPairs.iterator();
197	        // ensure leading delimiter matches
198	        if (inputString != null
199	            && inputString.length() > leadingDelimiter.length()
200	            && leadingDelimiter.equals(inputString.substring(0, leadingDelimiter.length()))) {
201	            byte[] input = inputString.getBytes(StandardCharsets.UTF_8);
202	            // grab the first key/delimiter pair
203	            DissectPair dissectPair = it.next();
204	            DissectKey key = dissectPair.key();
205	            byte[] delimiter = dissectPair.delimiter().getBytes(StandardCharsets.UTF_8);
206	            // start dissection after the first delimiter
207	            int i = leadingDelimiter.getBytes(StandardCharsets.UTF_8).length;
208	            int valueStart = i;
209	            int lookAheadMatches;
210	            // start walking the input string byte by byte, look ahead for matches where needed
211	            // if a match is found jump forward to the end of the match
212	            while (i < input.length) {
213	                lookAheadMatches = 0;
214	                // potential match between delimiter and input string
215	                if (delimiter.length > 0 && input[i] == delimiter[0]) {
216	                    // look ahead to see if the entire delimiter matches the input string
217	                    for (int j = 0; j < delimiter.length; j++) {
218	                        if (i + j < input.length && input[i + j] == delimiter[j]) {
219	                            lookAheadMatches++;
220	                        }
221	                    }
222	                    // found a full delimiter match
223	                    if (lookAheadMatches == delimiter.length) {
224	                        // record the key/value tuple
225	                        byte[] value = Arrays.copyOfRange(input, valueStart, i);
226	                        dissectMatch.add(key, new String(value, StandardCharsets.UTF_8));
227	                        // jump to the end of the match
228	                        i += lookAheadMatches;
229	                        // look for consecutive delimiters (e.g. a,,,,d,e)
230	                        while (i < input.length) {
231	                            lookAheadMatches = 0;
232	                            for (int j = 0; j < delimiter.length; j++) {
233	                                if (i + j < input.length && input[i + j] == delimiter[j]) {
234	                                    lookAheadMatches++;
235	                                }
236	                            }
237	                            // found consecutive delimiters
238	                            if (lookAheadMatches == delimiter.length) {
239	                                // jump to the end of the match
240	                                i += lookAheadMatches;
241	                                if (key.skipRightPadding() == false) {
242	                                    // progress the keys/delimiter if possible
243	                                    if (it.hasNext() == false) {
244	                                        break; // the while loop
245	                                    }
246	                                    dissectPair = it.next();
247	                                    key = dissectPair.key();
248	                                    // add the key with an empty value for the empty delimiter
249	                                    dissectMatch.add(key, "");
250	                                }
251	                            } else {
252	                                break; // the while loop
253	                            }
254	                        }
255	                        // progress the keys/delimiter if possible
256	                        if (it.hasNext() == false) {
257	                            break; // the for loop
258	                        }
259	                        dissectPair = it.next();
260	                        key = dissectPair.key();
261	                        delimiter = dissectPair.delimiter().getBytes(StandardCharsets.UTF_8);
262	                        // i is always one byte after the last found delimiter, aka the start of the next value
263	                        valueStart = i;
264	                    } else {
265	                        i++;
266	                    }
267	                } else {
268	                    i++;
269	                }
270	            }
271	            // the last key, grab the rest of the input (unless consecutive delimiters already grabbed the last key)
272	            // and there is no trailing delimiter
273	            if (dissectMatch.fullyMatched() == false && delimiter.length == 0) {
274	                byte[] value = Arrays.copyOfRange(input, valueStart, input.length);
275	                String valueString = new String(value, StandardCharsets.UTF_8);
276	                dissectMatch.add(key, valueString);
277	            }
278	        }
279	        Map<String, String> results = dissectMatch.getResults();
280	
281	        return dissectMatch.isValid(results) ? results : null;
282	    }
283	
284	    /**
285	     * Entry point to dissect a string into its parts.
286	     *
287	     * @param inputString The string to dissect
288	     * @return the key/value Map of the results
289	     * @throws DissectException if unable to dissect a pair into its parts.
290	     */
291	    public Map<String, String> forceParse(String inputString) {
292	        Map<String, String> results = parse(inputString);
293	        if (results == null) {
294	            throw new DissectException.FindMatch(pattern, inputString);
295	        }
296	        return results;
297	    }
298	
299	    /**
300	     * Returns the output keys produced by the instance (excluding named skip keys),
301	     * e.g. for the pattern <code>"%{a} %{b} %{?c}"</code> the result is <code>[a, b]</code>.
302	     * <p>
303	     * The result is an ordered set, where the entries are in the same order as they appear in the pattern.
304	     * <p>
305	     * The reference keys are returned with the name they have in the pattern, e.g. for <code>"%{*x} %{&amp;x}"</code>
306	     * the result is <code>[x]</code>.
307	     *
308	     * @return the output keys produced by the instance.
309	     */
310	    public Set<String> outputKeys() {
311	        Set<String> result = new LinkedHashSet<>(matchPairs.size());
312	        for (DissectPair matchPair : matchPairs) {
313	            if (matchPair.key.getModifier() != DissectKey.Modifier.NAMED_SKIP) {
314	                result.add(matchPair.key.getName());
315	            }
316	        }
317	        return result;
318	    }
319	
320	    /**
321	     * Returns the reference keys present in the pattern,
322	     * e.g. for the pattern <code>"%{a} %{b} %{*c} %{&amp;c} %{*d} %{&amp;d}"</code> it returns <code>[c, d]</code>.
323	     * <p>
324	     * The result is an ordered set, where the entries are in the same order as they appear in the pattern.
325	     *
326	     * @return the reference keys included in the pattern.
327	     */
328	    public Set<String> referenceKeys() {
329	        Set<String> result = new LinkedHashSet<>(matchPairs.size());
330	        for (DissectPair matchPair : matchPairs) {
331	            if (matchPair.key.getModifier() == DissectKey.Modifier.FIELD_NAME) {
332	                result.add(matchPair.key.getName());
333	            }
334	        }
335	        return result;
336	    }
337	
338	    /**
339	     * A tuple class to hold the dissect key and delimiter
340	     */
341	    private record DissectPair(DissectKey key, String delimiter) {}
342	
343	}
