/**
 * Collects, in pattern order, the names of all match pairs whose key modifier satisfies the given filter.
 * Shared by {@link #outputKeys()} and {@link #referenceKeys()}, which differ only in that predicate.
 */
private Set<String> collectKeyNames(Predicate<DissectKey.Modifier> modifierFilter) {
    Set<String> result = new LinkedHashSet<>(matchPairs.size());
    for (DissectPair matchPair : matchPairs) {
        if (modifierFilter.test(matchPair.key.getModifier())) {
            result.add(matchPair.key.getName());
        }
    }
    return result;
}

