/**
 * Counts how many leading bytes of {@code delimiter} match {@code input} starting at {@code offset}, without
 * reading past the end of {@code input}. A full delimiter match occurs when the returned count equals
 * {@code delimiter.length}. Extracted so the look-ahead used for both the initial and consecutive-delimiter
 * scans in {@link #parse(String)} lives in a single place.
 */
private static int countLeadingDelimiterMatch(byte[] input, int offset, byte[] delimiter) {
    int matches = 0;
    for (int j = 0; j < delimiter.length; j++) {
        if (offset + j < input.length && input[offset + j] == delimiter[j]) {
            matches++;
        }
    }
    return matches;
}

